The two loops have a loop-carried dependency on the accumulation into `x1[i]`/`x2[i]`. I'll restructure with local accumulator scalars to enable pipelining, and partition arrays for parallel access.

```cpp
#include "mvt.h"


void kernel_mvt(
		double x1[ N + 0],
		double x2[ N + 0],
		double y_1[ N + 0],
		double y_2[ N + 0],
		double A[ N + 0][N + 0])
{
#pragma HLS INLINE off

    const int n = N;

  int i, j;

  // First loop: x1[i] += sum_j A[i][j] * y_1[j]
  loop1_i:
  for (i = 0; i < n; i++) {
    double acc1 = x1[i];
    loop1_j:
    for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
      acc1 = acc1 + A[i][j] * y_1[j];
    }
    x1[i] = acc1;
  }

  // Second loop: x2[i] += sum_j A[j][i] * y_2[j]
  loop2_i:
  for (i = 0; i < n; i++) {
    double acc2 = x2[i];
    loop2_j:
    for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
      acc2 = acc2 + A[j][i] * y_2[j];
    }
    x2[i] = acc2;
  }
}


extern "C" {
void workload(
		double x1[ N + 0],
		double x2[ N + 0],
		double y_1[ N + 0],
		double y_2[ N + 0],
		double A[ N + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=x1  offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=x2  offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=y_1 offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=y_2 offset=slave bundle=gmem3
#pragma HLS INTERFACE m_axi port=A   offset=slave bundle=gmem4

#pragma HLS INTERFACE s_axilite port=x1  bundle=control
#pragma HLS INTERFACE s_axilite port=x2  bundle=control
#pragma HLS INTERFACE s_axilite port=y_1 bundle=control
#pragma HLS INTERFACE s_axilite port=y_2 bundle=control
#pragma HLS INTERFACE s_axilite port=A   bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    kernel_mvt(x1, x2, y_1, y_2, A);
}
}
```

Looking at this code, I'll apply tiling by staging the input arrays into local buffers and separating into load/compute/store phases.

For `kernel_mvt`, the key arrays are `A` (the large matrix), `y_1`, `y_2`, and the `x1`/`x2` outputs. Since both loops fully reuse the vectors `y_1` and `y_2`, I'll stage those locally. The matrix `A` is processed in tiles of rows.

```cpp
#include "mvt.h"
#include <string.h>


#define TILE 256

void kernel_mvt(
		double x1[ N + 0],
		double x2[ N + 0],
		double y_1[ N + 0],
		double y_2[ N + 0],
		double A[ N + 0][N + 0])
{
#pragma HLS INLINE off

    const int n = N;

    // ---- Local buffers ----
    double y1_local[N];
    double y2_local[N];
    double x1_local[N];
    double x2_local[N];

    // ---- LOAD vectors (reused across all rows) ----
    load_y1:
    for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
        y1_local[j] = y_1[j];
    }
    load_y2:
    for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
        y2_local[j] = y_2[j];
    }
    load_x1:
    for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        x1_local[i] = x1[i];
    }
    load_x2:
    for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        x2_local[i] = x2[i];
    }

    // ============================================================
    // First loop: x1[i] += sum_j A[i][j] * y_1[j]
    // Process A row-tiles
    // ============================================================
    loop1_tile:
    for (int it = 0; it < n; it += TILE) {
        int rows = (it + TILE <= n) ? TILE : (n - it);

        // LOAD tile of A rows into local buffer
        static double A_tile[TILE][N];
        load_A1:
        for (int r = 0; r < rows; r++) {
            for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
                A_tile[r][j] = A[it + r][j];
            }
        }

        // COMPUTE on local buffers
        compute1:
        for (int r = 0; r < rows; r++) {
            double acc1 = x1_local[it + r];
            loop1_j:
            for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
                acc1 = acc1 + A_tile[r][j] * y1_local[j];
            }
            x1_local[it + r] = acc1;
        }
    }

    // ============================================================
    // Second loop: x2[i] += sum_j A[j][i] * y_2[j]
    // Process column-tiles of A (i.e., output index i tiled)
    // ============================================================
    loop2_tile:
    for (int it = 0; it < n; it += TILE) {
        int cols = (it + TILE <= n) ? TILE : (n - it);

        // LOAD tile of A columns into local buffer (A[j][it..it+cols])
        static double A_tile2[N][TILE];
        load_A2:
        for (int j = 0; j < n; j++) {
            for (int c = 0; c < cols; c++) {
#pragma HLS PIPELINE II=1
                A_tile2[j][c] = A[j][it + c];
            }
        }

        // COMPUTE on local buffers
        compute2:
        for (int c = 0; c < cols; c++) {
            double acc2 = x2_local[it + c];
            loop2_j:
            for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
                acc2 = acc2 + A_tile2[j][c] * y2_local[j];
            }
            x2_local[it + c] = acc2;
        }
    }

    // ---- STORE results ----
    store_x1:
    for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        x1[i] = x1_local[i];
    }
    store_x2:
    for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        x2[i] = x2_local[i];
    }
}


extern "C" {
void workload(
		double x1[ N + 0],
		double x2[ N + 0],
		double y_1[ N + 0],
		double y_2[ N + 0],
		double A[ N + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=x1  offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=x2  offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=y_1 offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=y_2 offset=slave bundle=gmem3
#pragma HLS INTERFACE m_axi port=A   offset=slave bundle=gmem4

#pragma HLS INTERFACE s_axilite port=x1  bundle=control
#pragma HLS INTERFACE s_axilite port=x2  bundle=control
#pragma HLS INTERFACE s_axilite port=y_1 bundle=control
#pragma HLS INTERFACE s_axilite port=y_2 bundle=control
#pragma HLS INTERFACE s_axilite port=A   bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    kernel_mvt(x1, x2, y_1, y_2, A);
}
}
```

**Notes on this tiling step:**
- Vectors `y_1`, `y_2`, `x1`, `x2` are staged into local buffers since they are reused across all matrix rows/columns.
- The matrix `A` is processed in **row-tiles** for the first loop (`A[i][j]` row-major friendly) and **column-tiles** for the second loop (`A[j][i]`), each staged into a local tile buffer of `TILE` slices.
- Compute phases now read entirely from local buffers (`A_tile`, `y*_local`, `x*_local`), eliminating direct AXI accesses in the inner reduction loops.
- Boundary handling via `rows`/`cols` preserves correctness when `N` is not a multiple of `TILE` (here N=120 < TILE=256, so a single tile is used).
- Only tiling is applied; no double buffering, unrolling, or wide-bus coalescing added yet.

Looking at the code, the compute loops have floating-point accumulation as a loop-carried dependency, which limits the achievable II. I'll add pipeline pragmas with appropriate array partitioning and dependence pragmas where the dependencies are false.

The key bottleneck is the inner reduction loops (`loop1_j`, `loop2_j`) where `acc1`/`acc2` form a true loop-carried dependency. The pipeline II is limited by the floating-point add latency. To enable II=1 pipelining, I'll partition the arrays for parallel access and mark false dependencies on the output writes.

```cpp
#include "mvt.h"
#include <string.h>


#define TILE 256

void kernel_mvt(
		double x1[ N + 0],
		double x2[ N + 0],
		double y_1[ N + 0],
		double y_2[ N + 0],
		double A[ N + 0][N + 0])
{
#pragma HLS INLINE off

    const int n = N;

    // ---- Local buffers ----
    double y1_local[N];
    double y2_local[N];
    double x1_local[N];
    double x2_local[N];

    // ---- LOAD vectors (reused across all rows) ----
    load_y1:
    for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
        y1_local[j] = y_1[j];
    }
    load_y2:
    for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
        y2_local[j] = y_2[j];
    }
    load_x1:
    for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        x1_local[i] = x1[i];
    }
    load_x2:
    for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        x2_local[i] = x2[i];
    }

    // ============================================================
    // First loop: x1[i] += sum_j A[i][j] * y_1[j]
    // Process A row-tiles
    // ============================================================
    loop1_tile:
    for (int it = 0; it < n; it += TILE) {
#pragma HLS LOOP_TRIPCOUNT min=1 max=1
        int rows = (it + TILE <= n) ? TILE : (n - it);

        // LOAD tile of A rows into local buffer
        static double A_tile[TILE][N];
        load_A1:
        for (int r = 0; r < rows; r++) {
#pragma HLS LOOP_TRIPCOUNT min=120 max=120
            for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
                A_tile[r][j] = A[it + r][j];
            }
        }

        // COMPUTE on local buffers
        compute1:
        for (int r = 0; r < rows; r++) {
#pragma HLS LOOP_TRIPCOUNT min=120 max=120
            double acc1 = x1_local[it + r];
            loop1_j:
            for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
                acc1 = acc1 + A_tile[r][j] * y1_local[j];
            }
            x1_local[it + r] = acc1;
        }
    }

    // ============================================================
    // Second loop: x2[i] += sum_j A[j][i] * y_2[j]
    // Process column-tiles of A (i.e., output index i tiled)
    // ============================================================
    loop2_tile:
    for (int it = 0; it < n; it += TILE) {
#pragma HLS LOOP_TRIPCOUNT min=1 max=1
        int cols = (it + TILE <= n) ? TILE : (n - it);

        // LOAD tile of A columns into local buffer (A[j][it..it+cols])
        static double A_tile2[N][TILE];
        load_A2:
        for (int j = 0; j < n; j++) {
#pragma HLS LOOP_TRIPCOUNT min=120 max=120
            for (int c = 0; c < cols; c++) {
#pragma HLS PIPELINE II=1
                A_tile2[j][c] = A[j][it + c];
            }
        }

        // COMPUTE on local buffers
        compute2:
        for (int c = 0; c < cols; c++) {
#pragma HLS LOOP_TRIPCOUNT min=120 max=120
            double acc2 = x2_local[it + c];
            loop2_j:
            for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
                acc2 = acc2 + A_tile2[j][c] * y2_local[j];
            }
            x2_local[it + c] = acc2;
        }
    }

    // ---- STORE results ----
    store_x1:
    for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        x1[i] = x1_local[i];
    }
    store_x2:
    for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        x2[i] = x2_local[i];
    }
}


extern "C" {
void workload(
		double x1[ N + 0],
		double x2[ N + 0],
		double y_1[ N + 0],
		double y_2[ N + 0],
		double A[ N + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=x1  offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=x2  offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=y_1 offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=y_2 offset=slave bundle=gmem3
#pragma HLS INTERFACE m_axi port=A   offset=slave bundle=gmem4

#pragma HLS INTERFACE s_axilite port=x1  bundle=control
#pragma HLS INTERFACE s_axilite port=x2  bundle=control
#pragma HLS INTERFACE s_axilite port=y_1 bundle=control
#pragma HLS INTERFACE s_axilite port=y_2 bundle=control
#pragma HLS INTERFACE s_axilite port=A   bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    kernel_mvt(x1, x2, y_1, y_2, A);
}
}
```

Note: The inner reduction loops (`loop1_j`, `loop2_j`) carry a true dependency through the floating-point accumulator `acc1`/`acc2`, so II=1 may not be achievable for those without reduction restructuring (which would be a separate transformation/UNROLL step). The PIPELINE pragmas here will allow the scheduler to pipeline what it legally can; the load/store loops will pipeline cleanly at II=1. I intentionally did not add `DEPENDENCE inter false` on the accumulator loops since that would be a real loop-carried dependence (per the guards). The `LOOP_TRIPCOUNT` pragmas help the tool estimate latency for the variable-bound tile and inner loops.

Looking at the code, the inner reduction loops (`loop1_j`, `loop2_j`) are pipelined floating-point reductions. The best unroll targets are these inner loops, but they have loop-carried dependencies on the accumulator. I'll unroll the inner loops with partial sums to break the dependency, and partition the relevant arrays/buffers to match.

I'll unroll by factor 4 (120 is divisible by 4), partitioning the tile buffers and y-vectors cyclically.

```cpp
#include "mvt.h"
#include <string.h>


#define TILE 256
#define UF 4

void kernel_mvt(
		double x1[ N + 0],
		double x2[ N + 0],
		double y_1[ N + 0],
		double y_2[ N + 0],
		double A[ N + 0][N + 0])
{
#pragma HLS INLINE off

    const int n = N;

    // ---- Local buffers ----
    double y1_local[N];
    double y2_local[N];
    double x1_local[N];
    double x2_local[N];
#pragma HLS ARRAY_PARTITION variable=y1_local cyclic factor=UF dim=1
#pragma HLS ARRAY_PARTITION variable=y2_local cyclic factor=UF dim=1

    // ---- LOAD vectors (reused across all rows) ----
    load_y1:
    for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
        y1_local[j] = y_1[j];
    }
    load_y2:
    for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
        y2_local[j] = y_2[j];
    }
    load_x1:
    for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        x1_local[i] = x1[i];
    }
    load_x2:
    for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        x2_local[i] = x2[i];
    }

    // ============================================================
    // First loop: x1[i] += sum_j A[i][j] * y_1[j]
    // Process A row-tiles
    // ============================================================
    loop1_tile:
    for (int it = 0; it < n; it += TILE) {
#pragma HLS LOOP_TRIPCOUNT min=1 max=1
        int rows = (it + TILE <= n) ? TILE : (n - it);

        // LOAD tile of A rows into local buffer
        static double A_tile[TILE][N];
#pragma HLS ARRAY_PARTITION variable=A_tile cyclic factor=UF dim=2
        load_A1:
        for (int r = 0; r < rows; r++) {
#pragma HLS LOOP_TRIPCOUNT min=120 max=120
            for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
                A_tile[r][j] = A[it + r][j];
            }
        }

        // COMPUTE on local buffers
        compute1:
        for (int r = 0; r < rows; r++) {
#pragma HLS LOOP_TRIPCOUNT min=120 max=120
            double acc1 = x1_local[it + r];
            loop1_j:
            for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=UF
                acc1 = acc1 + A_tile[r][j] * y1_local[j];
            }
            x1_local[it + r] = acc1;
        }
    }

    // ============================================================
    // Second loop: x2[i] += sum_j A[j][i] * y_2[j]
    // Process column-tiles of A (i.e., output index i tiled)
    // ============================================================
    loop2_tile:
    for (int it = 0; it < n; it += TILE) {
#pragma HLS LOOP_TRIPCOUNT min=1 max=1
        int cols = (it + TILE <= n) ? TILE : (n - it);

        // LOAD tile of A columns into local buffer (A[j][it..it+cols])
        static double A_tile2[N][TILE];
#pragma HLS ARRAY_PARTITION variable=A_tile2 cyclic factor=UF dim=1
        load_A2:
        for (int j = 0; j < n; j++) {
#pragma HLS LOOP_TRIPCOUNT min=120 max=120
            for (int c = 0; c < cols; c++) {
#pragma HLS PIPELINE II=1
                A_tile2[j][c] = A[j][it + c];
            }
        }

        // COMPUTE on local buffers
        compute2:
        for (int c = 0; c < cols; c++) {
#pragma HLS LOOP_TRIPCOUNT min=120 max=120
            double acc2 = x2_local[it + c];
            loop2_j:
            for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=UF
                acc2 = acc2 + A_tile2[j][c] * y2_local[j];
            }
            x2_local[it + c] = acc2;
        }
    }

    // ---- STORE results ----
    store_x1:
    for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        x1[i] = x1_local[i];
    }
    store_x2:
    for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        x2[i] = x2_local[i];
    }
}


extern "C" {
void workload(
		double x1[ N + 0],
		double x2[ N + 0],
		double y_1[ N + 0],
		double y_2[ N + 0],
		double A[ N + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=x1  offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=x2  offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=y_1 offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=y_2 offset=slave bundle=gmem3
#pragma HLS INTERFACE m_axi port=A   offset=slave bundle=gmem4

#pragma HLS INTERFACE s_axilite port=x1  bundle=control
#pragma HLS INTERFACE s_axilite port=x2  bundle=control
#pragma HLS INTERFACE s_axilite port=y_1 bundle=control
#pragma HLS INTERFACE s_axilite port=y_2 bundle=control
#pragma HLS INTERFACE s_axilite port=A   bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    kernel_mvt(x1, x2, y_1, y_2, A);
}
}
```

**Notes on this unroll step:**
- Applied `#pragma HLS UNROLL factor=4` to the inner reduction loops `loop1_j` and `loop2_j`, which dominate arithmetic latency.
- Partitioned `y1_local`/`y2_local` and the tile buffers cyclically by factor 4 (matching `dim=2` for `A_tile` row-access and `dim=1` for `A_tile2` column-access) so 4 multiply-add operands can be fetched in parallel.
- Factor 4 evenly divides N=120. This is a floating-point reduction; HLS will partial-sum/reassociate the unrolled iterations (acceptable under typical FP tolerance for this benchmark).

Looking at this code, the tiles have TILE=256 but N=120, so there's only **one tile** per loop (trip count 1). Double buffering across tiles wouldn't help here since each loop runs a single iteration.

However, following the requested optimization, I'll restructure to use double-buffered load/compute functions with a flag parameter, alternating buffers across the row/column iterations within each compute phase. I'll process rows in chunks and overlap loading the next chunk's A-tile data with computing the current chunk.

```cpp
#include "mvt.h"
#include <string.h>


#define TILE 60
#define UF 4

// ---- Double-buffered LOAD of A row-tile (loop 1) ----
static void load_A1(double A[N + 0][N + 0], double A_buf1[TILE][N],
                    double A_buf2[TILE][N], int it, int rows, int flag)
{
#pragma HLS INLINE off
    if (flag == 0) {
        for (int r = 0; r < rows; r++) {
#pragma HLS LOOP_TRIPCOUNT min=60 max=60
            for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
                A_buf1[r][j] = A[it + r][j];
            }
        }
    } else {
        for (int r = 0; r < rows; r++) {
#pragma HLS LOOP_TRIPCOUNT min=60 max=60
            for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
                A_buf2[r][j] = A[it + r][j];
            }
        }
    }
}

// ---- Double-buffered COMPUTE of loop 1 ----
static void compute_A1(double A_buf1[TILE][N], double A_buf2[TILE][N],
                       double x1_local[N], double y1_local[N],
                       int it, int rows, int flag)
{
#pragma HLS INLINE off
    if (flag == 0) {
        for (int r = 0; r < rows; r++) {
#pragma HLS LOOP_TRIPCOUNT min=60 max=60
            double acc1 = x1_local[it + r];
            for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=UF
                acc1 = acc1 + A_buf1[r][j] * y1_local[j];
            }
            x1_local[it + r] = acc1;
        }
    } else {
        for (int r = 0; r < rows; r++) {
#pragma HLS LOOP_TRIPCOUNT min=60 max=60
            double acc1 = x1_local[it + r];
            for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=UF
                acc1 = acc1 + A_buf2[r][j] * y1_local[j];
            }
            x1_local[it + r] = acc1;
        }
    }
}

// ---- Double-buffered LOAD of A column-tile (loop 2) ----
static void load_A2(double A[N + 0][N + 0], double A_buf1[N][TILE],
                    double A_buf2[N][TILE], int it, int cols, int flag)
{
#pragma HLS INLINE off
    if (flag == 0) {
        for (int j = 0; j < N; j++) {
#pragma HLS LOOP_TRIPCOUNT min=120 max=120
            for (int c = 0; c < cols; c++) {
#pragma HLS PIPELINE II=1
                A_buf1[j][c] = A[j][it + c];
            }
        }
    } else {
        for (int j = 0; j < N; j++) {
#pragma HLS LOOP_TRIPCOUNT min=120 max=120
            for (int c = 0; c < cols; c++) {
#pragma HLS PIPELINE II=1
                A_buf2[j][c] = A[j][it + c];
            }
        }
    }
}

// ---- Double-buffered COMPUTE of loop 2 ----
static void compute_A2(double A_buf1[N][TILE], double A_buf2[N][TILE],
                       double x2_local[N], double y2_local[N],
                       int it, int cols, int flag)
{
#pragma HLS INLINE off
    if (flag == 0) {
        for (int c = 0; c < cols; c++) {
#pragma HLS LOOP_TRIPCOUNT min=60 max=60
            double acc2 = x2_local[it + c];
            for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=UF
                acc2 = acc2 + A_buf1[j][c] * y2_local[j];
            }
            x2_local[it + c] = acc2;
        }
    } else {
        for (int c = 0; c < cols; c++) {
#pragma HLS LOOP_TRIPCOUNT min=60 max=60
            double acc2 = x2_local[it + c];
            for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=UF
                acc2 = acc2 + A_buf2[j][c] * y2_local[j];
            }
            x2_local[it + c] = acc2;
        }
    }
}

void kernel_mvt(
		double x1[ N + 0],
		double x2[ N + 0],
		double y_1[ N + 0],
		double y_2[ N + 0],
		double A[ N + 0][N + 0])
{
#pragma HLS INLINE off

    const int n = N;

    // ---- Local buffers ----
    double y1_local[N];
    double y2_local[N];
    double x1_local[N];
    double x2_local[N];
#pragma HLS ARRAY_PARTITION variable=y1_local cyclic factor=UF dim=1
#pragma HLS ARRAY_PARTITION variable=y2_local cyclic factor=UF dim=1

    // ---- LOAD vectors (reused across all rows) ----
    load_y1:
    for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
        y1_local[j] = y_1[j];
    }
    load_y2:
    for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
        y2_local[j] = y_2[j];
    }
    load_x1:
    for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        x1_local[i] = x1[i];
    }
    load_x2:
    for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        x2_local[i] = x2[i];
    }

    // ============================================================
    // First loop: x1[i] += sum_j A[i][j] * y_1[j]
    // Double-buffered row tiling
    // ============================================================
    static double A1_buf1[TILE][N];
    static double A1_buf2[TILE][N];
#pragma HLS ARRAY_PARTITION variable=A1_buf1 cyclic factor=UF dim=2
#pragma HLS ARRAY_PARTITION variable=A1_buf2 cyclic factor=UF dim=2

    {
        // Number of tiles
        int num_tiles = (n + TILE - 1) / TILE;

        // Prologue: load first tile into buffer 0
        int it0 = 0;
        int rows0 = (it0 + TILE <= n) ? TILE : (n - it0);
        load_A1(A, A1_buf1, A1_buf2, it0, rows0, 0);

        loop1_tile:
        for (int t = 1; t < num_tiles; t++) {
#pragma HLS LOOP_TRIPCOUNT min=1 max=2
            int flag_load = t & 1;          // buffer to load tile t
            int flag_comp = (t - 1) & 1;    // buffer to compute tile t-1

            int it_load = t * TILE;
            int rows_load = (it_load + TILE <= n) ? TILE : (n - it_load);

            int it_comp = (t - 1) * TILE;
            int rows_comp = (it_comp + TILE <= n) ? TILE : (n - it_comp);

            // Load tile t while computing tile t-1 (overlap)
            load_A1(A, A1_buf1, A1_buf2, it_load, rows_load, flag_load);
            compute_A1(A1_buf1, A1_buf2, x1_local, y1_local, it_comp, rows_comp, flag_comp);
        }

        // Epilogue: compute last tile
        int t_last = num_tiles - 1;
        int flag_last = t_last & 1;
        int it_last = t_last * TILE;
        int rows_last = (it_last + TILE <= n) ? TILE : (n - it_last);
        compute_A1(A1_buf1, A1_buf2, x1_local, y1_local, it_last, rows_last, flag_last);
    }

    // ============================================================
    // Second loop: x2[i] += sum_j A[j][i] * y_2[j]
    // Double-buffered column tiling
    // ============================================================
    static double A2_buf1[N][TILE];
    static double A2_buf2[N][TILE];
#pragma HLS ARRAY_PARTITION variable=A2_buf1 cyclic factor=UF dim=1
#pragma HLS ARRAY_PARTITION variable=A2_buf2 cyclic factor=UF dim=1

    {
        int num_tiles = (n + TILE - 1) / TILE;

        // Prologue: load first column tile into buffer 0
        int it0 = 0;
        int cols0 = (it0 + TILE <= n) ? TILE : (n - it0);
        load_A2(A, A2_buf1, A2_buf2, it0, cols0, 0);

        loop2_tile:
        for (int t = 1; t < num_tiles; t++) {
#pragma HLS LOOP_TRIPCOUNT min=1 max=2
            int flag_load = t & 1;
            int flag_comp = (t - 1) & 1;

            int it_load = t * TILE;
            int cols_load = (it_load + TILE <= n) ? TILE : (n - it_load);

            int it_comp = (t - 1) * TILE;
            int cols_comp = (it_comp + TILE <= n) ? TILE : (n - it_comp);

            load_A2(A, A2_buf1, A2_buf2, it_load, cols_load, flag_load);
            compute_A2(A2_buf1, A2_buf2, x2_local, y2_local, it_comp, cols_comp, flag_comp);
        }

        // Epilogue: compute last tile
        int t_last = num_tiles - 1;
        int flag_last = t_last & 1;
        int it_last = t_last * TILE;
        int cols_last = (it_last + TILE <= n) ? TILE : (n - it_last);
        compute_A2(A2_buf1, A2_buf2, x2_local, y2_local, it_last, cols_last, flag_last);
    }

    // ---- STORE results ----
    store_x1:
    for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        x1[i] = x1_local[i];
    }
    store_x2:
    for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        x2[i] = x2_local[i];
    }
}


