```cpp
#include "mvt.h"
#include <string.h>
#include <ap_int.h>


#define TILE 60
#define UF 4

// ---- Wide bus definitions (self-contained, since common/mc.h is unavailable) ----
#ifndef LARGE_BUS
#define LARGE_BUS 512
#endif
typedef ap_uint<LARGE_BUS> MARS_WIDE_BUS_TYPE;

// Number of doubles per wide bus word
#define DOUBLES_PER_BUS (LARGE_BUS / 64)

// Coalesced wide-bus read of 'bytes' bytes (doubles) from global memory
// 'byte_offset' is the byte offset into the flat buffer.
static void memcpy_wide_bus_read_double(double *local, MARS_WIDE_BUS_TYPE *bus,
                                        long byte_offset, long bytes)
{
#pragma HLS INLINE off
    long num_doubles = bytes / (long)sizeof(double);
    long word_base = byte_offset / (long)sizeof(MARS_WIDE_BUS_TYPE);
    long elem_in_word0 = (byte_offset / (long)sizeof(double)) % DOUBLES_PER_BUS;

    long li = 0;
    long w = word_base;
    long lane = elem_in_word0;

    while (li < num_doubles) {
#pragma HLS LOOP_TRIPCOUNT min=1 max=32
        MARS_WIDE_BUS_TYPE word = bus[w];
        for (long k = lane; k < DOUBLES_PER_BUS && li < num_doubles; k++) {
#pragma HLS PIPELINE II=1
            ap_uint<64> raw = word.range(k * 64 + 63, k * 64);
            unsigned long long bits = (unsigned long long)raw;
            double val;
            memcpy(&val, &bits, sizeof(double));
            local[li++] = val;
        }
        lane = 0;
        w++;
    }
}

// Coalesced wide-bus write of 'bytes' bytes (doubles) to global memory
static void memcpy_wide_bus_write_double(double *local, MARS_WIDE_BUS_TYPE *bus,
                                         long byte_offset, long bytes)
{
#pragma HLS INLINE off
    long num_doubles = bytes / (long)sizeof(double);
    long word_base = byte_offset / (long)sizeof(MARS_WIDE_BUS_TYPE);
    long elem_in_word0 = (byte_offset / (long)sizeof(double)) % DOUBLES_PER_BUS;

    long li = 0;
    long w = word_base;
    long lane = elem_in_word0;

    while (li < num_doubles) {
#pragma HLS LOOP_TRIPCOUNT min=1 max=32
        MARS_WIDE_BUS_TYPE word = bus[w];
        for (long k = lane; k < DOUBLES_PER_BUS && li < num_doubles; k++) {
#pragma HLS PIPELINE II=1
            double val = local[li++];
            unsigned long long bits;
            memcpy(&bits, &val, sizeof(double));
            word.range(k * 64 + 63, k * 64) = ap_uint<64>(bits);
        }
        bus[w] = word;
        lane = 0;
        w++;
    }
}

